ddl:
CREATE TABLE Worker (
    Contact_number VARCHAR(255),
    Name VARCHAR(255),
    Worker_ID INTEGER PRIMARY KEY
);

CREATE TABLE Workshop (
    Workshop_ID INTEGER PRIMARY KEY,
    Workshop_address VARCHAR(255),
    Workshop_name VARCHAR(255)
);

CREATE TABLE Raw_material (
    Raw_material_ID INTEGER PRIMARY KEY,
    Raw_material_name VARCHAR(255)
);

CREATE TABLE Product (
    Product_ID INTEGER PRIMARY KEY,
    Product_name VARCHAR(255)
);

CREATE TABLE Workshop_raw_material_management (
    Inventory_quantity INTEGER,
    Raw_material_ID INTEGER NOT NULL,
    Workshop_ID INTEGER NOT NULL,
    PRIMARY KEY (Workshop_ID, Raw_material_ID),
    FOREIGN KEY (Raw_material_ID) REFERENCES Raw_material(Raw_material_ID),
    FOREIGN KEY (Workshop_ID) REFERENCES Workshop(Workshop_ID)
);

CREATE TABLE Product_processing_task (
    Processing_task_ID INTEGER PRIMARY KEY,
    Processing_time DATETIME,
    Product_ID INTEGER NOT NULL,
    Product_quality_rating INTEGER,
    Production_quantity INTEGER,
    FOREIGN KEY (Product_ID) REFERENCES Product(Product_ID)
);

CREATE TABLE Worker_processing_product (
    Processing_task_ID INTEGER NOT NULL,
    Worker_ID INTEGER NOT NULL,
    PRIMARY KEY (Processing_task_ID, Worker_ID),
    FOREIGN KEY (Processing_task_ID) REFERENCES Product_processing_task(Processing_task_ID),
    FOREIGN KEY (Worker_ID) REFERENCES Worker(Worker_ID)
);

CREATE TABLE Raw_materials_involved_in_product_processing (
    Processing_task_ID INTEGER NOT NULL,
    Raw_material_ID INTEGER NOT NULL,
    PRIMARY KEY (Processing_task_ID, Raw_material_ID),
    FOREIGN KEY (Processing_task_ID) REFERENCES Product_processing_task(Processing_task_ID),
    FOREIGN KEY (Raw_material_ID) REFERENCES Raw_material(Raw_material_ID)
);
